# ==============================================================================
# 02_run_cicero_from_export.R
#
# CICERO PIPELINE - MEMORY AWARE / |COACCESS| > 0.2
#
# Environment:
#   R 4.5.3
#   monocle 2.x
#   monocle3 1.4.27
#   cicero 1.29.2
#   Matrix 1.7.6
#
# Input:
#   ./cicero_export/
#
# Output:
#   ./v3_coacc_cicero/
#
# IMPORTANT:
#
#   1. Uses Monocle 2 CellDataSet because Cicero 1.29.2 expects
#      class "CellDataSet".
#
#   2. MatrixMarket ngTMatrix is converted directly to dgCMatrix.
#
#   3. Full Cicero connections are temporarily generated by
#      assemble_connections().
#
#   4. Immediately after assembly, only:
#
#          abs(coaccess) > 0.2
#
#      is retained.
#
#   5. The filtered table is written to disk.
#
#   6. Full connections + Cicero models + temporary large objects are
#      removed and garbage collection is forced.
#
#   7. CCAN generation uses ONLY the filtered >0.2 connections and explicitly
#      sets coaccess_cutoff_override = 0.2.
#
#   8. Therefore the output connection files contain ONLY |coaccess| > 0.2.
#
# Checkpoint:
#   Existing filtered connection file causes that group to be skipped.
# ==============================================================================


# ==============================================================================
# Libraries
# ==============================================================================

suppressPackageStartupMessages({

  library(monocle)
  library(cicero)
  library(Matrix)
  library(VGAM)
  library(stringr)

})


options(stringsAsFactors = FALSE)

set.seed(123)


# ==============================================================================
# Parameters
# ==============================================================================

export_dir <- "./cicero_export/"
out_dir <- "./v3_coacc_cicero/"

dir.create(
  out_dir,
  showWarnings = FALSE,
  recursive = TRUE
)


# ------------------------------------------------------------------------------
# Cicero parameters
# ------------------------------------------------------------------------------

CICERO_K <- 50

CICERO_DISTANCE_CONSTRAINT <- 5e5

CICERO_WINDOW <- 1e6


# ------------------------------------------------------------------------------
# NEW threshold
# ------------------------------------------------------------------------------

COACCESS_THRESHOLD <- 0.2


# ==============================================================================
# Environment information
# ==============================================================================

message("")
message("============================================================")
message(" CICERO FROM EXPORT")
message(" MONOCLE 2 CellDataSet")
message(" MEMORY-AWARE |COACCESS| > ", COACCESS_THRESHOLD)
message("============================================================")

message("R:        ", R.version.string)

message(
  "monocle:  ",
  as.character(
    packageVersion("monocle")
  )
)

message(
  "monocle3: ",
  as.character(
    packageVersion("monocle3")
  )
)

message(
  "cicero:   ",
  as.character(
    packageVersion("cicero")
  )
)

message(
  "Matrix:   ",
  as.character(
    packageVersion("Matrix")
  )
)

message("============================================================")
message("")


# ==============================================================================
# Helper function: classify peak-pair type
# ==============================================================================

classify_pair_type <- function(
  peak1_ids,
  peak2_ids,
  lookup
) {

  t1 <- lookup[
    peak1_ids
  ]

  t2 <- lookup[
    peak2_ids
  ]


  t1[
    is.na(t1) | t1 == ""
  ] <- "Unknown"

  t2[
    is.na(t2) | t2 == ""
  ] <- "Unknown"


  simplify_type <- function(x) {

    ifelse(
      x == "Promoter",
      "Promoter",
      ifelse(
        x == "Unknown",
        "Unknown",
        "Distal"
      )
    )
  }


  s1 <- simplify_type(t1)

  s2 <- simplify_type(t2)


  apply(
    cbind(
      s1,
      s2
    ),
    1,
    function(r) {

      paste(
        sort(r),
        collapse = "-"
      )
    }
  )
}


# ==============================================================================
# Check export directory
# ==============================================================================

if (!dir.exists(export_dir)) {

  stop(
    "Export directory does not exist: ",
    export_dir
  )
}


# ==============================================================================
# Read genomic coordinates
# ==============================================================================

genomic_coords_file <- file.path(
  export_dir,
  "genomic_coords.tsv"
)


if (!file.exists(
  genomic_coords_file
)) {

  stop(
    "Missing genomic_coords.tsv: ",
    genomic_coords_file
  )
}


genomic_coords <- read.delim(
  genomic_coords_file,
  stringsAsFactors = FALSE,
  check.names = FALSE
)


message(
  "[CHECK] Genomic coordinate rows: ",
  nrow(genomic_coords)
)


# ==============================================================================
# Read peak type lookup
# ==============================================================================

peak_type_file <- file.path(
  export_dir,
  "peak_type_lookup.tsv"
)


if (!file.exists(
  peak_type_file
)) {

  stop(
    "Missing peak_type_lookup.tsv: ",
    peak_type_file
  )
}


peak_type_df <- read.delim(
  peak_type_file,
  stringsAsFactors = FALSE,
  check.names = FALSE
)


if (!all(
  c(
    "peak_id",
    "peakType"
  ) %in% colnames(peak_type_df)
)) {

  stop(
    "peak_type_lookup.tsv must contain peak_id and peakType"
  )
}


peak_type_lookup <- setNames(
  peak_type_df$peakType,
  peak_type_df$peak_id
)


# ==============================================================================
# Find groups
# ==============================================================================

groups_dirs <- list.dirs(
  export_dir,
  full.names = FALSE,
  recursive = FALSE
)


message(
  "[CHECK] Groups found in export: ",
  length(groups_dirs)
)


if (length(groups_dirs) == 0) {

  stop(
    "No group directories found in ",
    export_dir
  )
}


# ==============================================================================
# Output containers
# ==============================================================================

cicero_summary <- list()

ccan_summary <- list()

pairtype_summary <- list()

skip_log <- list()


# ==============================================================================
# Main loop
# ==============================================================================

for (grp in groups_dirs) {


  # ============================================================================
  # Paths
  # ============================================================================

  grp_dir <- file.path(
    export_dir,
    grp
  )


  outfile <- file.path(
    out_dir,
    paste0(
      "cicero_",
      grp,
      "_connections.tsv"
    )
  )


  ccan_outfile <- file.path(
    out_dir,
    paste0(
      "cicero_",
      grp,
      "_ccans.tsv"
    )
  )


  # ============================================================================
  # Checkpoint
  # ============================================================================

  if (file.exists(outfile)) {

    message(
      "[SKIP] ",
      grp,
      " -- filtered connection file already exists."
    )

    next
  }


  # ============================================================================
  # Group header
  # ============================================================================

  message("")
  message("============================================================")
  message(" Processing group: ", grp)
  message(" Threshold: |coaccess| > ", COACCESS_THRESHOLD)
  message("============================================================")


  t_grp <- Sys.time()


  # ============================================================================
  # Required input files
  # ============================================================================

  required_files <- c(
    "peak_matrix.mtx",
    "peak_ids.txt",
    "cell_barcodes.txt",
    "peak_coords.tsv"
  )


  missing_files <- required_files[
    !file.exists(
      file.path(
        grp_dir,
        required_files
      )
    )
  ]


  if (length(missing_files) > 0) {

    message(
      "[ERROR] Missing files: ",
      paste(
        missing_files,
        collapse = ", "
      )
    )


    skip_log[[grp]] <- paste(
      "missing files:",
      paste(
        missing_files,
        collapse = ", "
      )
    )


    next
  }


  # ============================================================================
  # Peak IDs
  # ============================================================================

  peak_ids <- tryCatch(

    readLines(
      file.path(
        grp_dir,
        "peak_ids.txt"
      )
    ),

    error = function(e) {

      message(
        "[ERROR] peak IDs: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(peak_ids)) {

    skip_log[[grp]] <- "failed: peak IDs"

    next
  }


  peak_ids <- peak_ids[
    nzchar(peak_ids)
  ]


  # ============================================================================
  # Cell IDs
  # ============================================================================

  cell_ids <- tryCatch(

    readLines(
      file.path(
        grp_dir,
        "cell_barcodes.txt"
      )
    ),

    error = function(e) {

      message(
        "[ERROR] cell IDs: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(cell_ids)) {

    skip_log[[grp]] <- "failed: cell IDs"

    next
  }


  cell_ids <- cell_ids[
    nzchar(cell_ids)
  ]


  message(
    "[DEBUG] Peak IDs: ",
    length(peak_ids)
  )


  message(
    "[DEBUG] Cell IDs: ",
    length(cell_ids)
  )


  # ============================================================================
  # Read MatrixMarket
  # ============================================================================

  message(
    "[DEBUG] Reading peak_matrix.mtx..."
  )


  mat <- tryCatch(

    Matrix::readMM(
      file.path(
        grp_dir,
        "peak_matrix.mtx"
      )
    ),

    error = function(e) {

      message(
        "[ERROR] readMM: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(mat)) {

    skip_log[[grp]] <- "failed: readMM"

    next
  }


  message(
    "[DEBUG] MatrixMarket class: ",
    paste(
      class(mat),
      collapse = ", "
    )
  )


  message(
    "[DEBUG] Matrix dimensions: ",
    paste(
      dim(mat),
      collapse = " x "
    )
  )


  # ============================================================================
  # Convert ngTMatrix -> dgCMatrix
  # ============================================================================

  if (inherits(
    mat,
    "ngTMatrix"
  )) {

    message(
      "[DEBUG] Detected ngTMatrix."
    )


    message(
      "[DEBUG] Treating stored entries as binary accessibility = 1."
    )


    mat <- tryCatch(

      Matrix::sparseMatrix(
        i = mat@i + 1L,
        j = mat@j + 1L,
        x = rep(
          1,
          length(mat@i)
        ),
        dims = dim(mat),
        repr = "C"
      ),

      error = function(e) {

        message(
          "[ERROR] ngTMatrix conversion: ",
          conditionMessage(e)
        )

        NULL
      }
    )

  } else {

    mat <- tryCatch(

      methods::as(
        mat,
        "dgCMatrix"
      ),

      error = function(e) {

        message(
          "[ERROR] Matrix conversion: ",
          conditionMessage(e)
        )

        NULL
      }
    )
  }


  if (is.null(mat)) {

    skip_log[[grp]] <- "failed: matrix conversion"

    next
  }


  if (!inherits(
    mat,
    "dgCMatrix"
  )) {

    message(
      "[ERROR] Matrix is not dgCMatrix: ",
      paste(
        class(mat),
        collapse = ", "
      )
    )


    skip_log[[grp]] <- "failed: matrix class"

    next
  }


  message(
    "[DEBUG] Final matrix class: ",
    paste(
      class(mat),
      collapse = ", "
    )
  )


  message(
    "[DEBUG] Nonzero entries: ",
    length(mat@x)
  )


  # ============================================================================
  # Matrix dimensions
  # ============================================================================

  if (nrow(mat) != length(peak_ids)) {

    message(
      "[ERROR] Matrix rows = ",
      nrow(mat),
      "; peak IDs = ",
      length(peak_ids)
    )


    skip_log[[grp]] <- "failed: peak count mismatch"

    next
  }


  if (ncol(mat) != length(cell_ids)) {

    message(
      "[ERROR] Matrix columns = ",
      ncol(mat),
      "; cell IDs = ",
      length(cell_ids)
    )


    skip_log[[grp]] <- "failed: cell count mismatch"

    next
  }


  # ============================================================================
  # Assign IDs
  # ============================================================================

  rownames(mat) <- peak_ids

  colnames(mat) <- cell_ids


  message(
    "[DEBUG] Peak matrix: ",
    nrow(mat),
    " peaks x ",
    ncol(mat),
    " cells"
  )


  # ============================================================================
  # Read peak metadata
  # ============================================================================

  peak_df <- tryCatch(

    read.delim(
      file.path(
        grp_dir,
        "peak_coords.tsv"
      ),
      stringsAsFactors = FALSE,
      check.names = FALSE
    ),

    error = function(e) {

      message(
        "[ERROR] peak_coords.tsv: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(peak_df)) {

    skip_log[[grp]] <- "failed: peak metadata"

    next
  }


  if (nrow(peak_df) != length(peak_ids)) {

    message(
      "[ERROR] Peak metadata rows = ",
      nrow(peak_df),
      "; peak IDs = ",
      length(peak_ids)
    )


    skip_log[[grp]] <- "failed: peak metadata count"

    next
  }


  rownames(peak_df) <- peak_ids


  # ============================================================================
  # Add gene_short_name
  # ============================================================================

  if (!"gene_short_name" %in% colnames(peak_df)) {

    peak_df$gene_short_name <- rownames(peak_df)

    message(
      "[DEBUG] Added gene_short_name."
    )
  }


  # ============================================================================
  # Cell metadata
  # ============================================================================

  cell_df <- data.frame(
    row.names = cell_ids
  )


  # ============================================================================
  # AnnotatedDataFrames
  # ============================================================================

  pd <- methods::new(
    "AnnotatedDataFrame",
    data = cell_df
  )


  fd <- methods::new(
    "AnnotatedDataFrame",
    data = peak_df
  )


  # ============================================================================
  # Create Monocle 2 CellDataSet
  # ============================================================================

  message(
    "[DEBUG] Creating Monocle 2 CellDataSet..."
  )


  cds <- tryCatch(

    suppressWarnings(
      monocle::newCellDataSet(
        mat,
        phenoData = pd,
        featureData = fd,
        expressionFamily = VGAM::binomialff(),
        lowerDetectionLimit = 0
      )
    ),

    error = function(e) {

      message(
        "[ERROR] newCellDataSet: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(cds)) {

    skip_log[[grp]] <- "failed: newCellDataSet"

    next
  }


  message(
    "[DEBUG] CellDataSet created successfully."
  )


  message(
    "[DEBUG] CDS dimensions: ",
    nrow(cds),
    " features x ",
    ncol(cds),
    " cells"
  )


  if (!methods::is(
    cds,
    "CellDataSet"
  )) {

    message(
      "[ERROR] Object is not a CellDataSet."
    )


    skip_log[[grp]] <- "failed: CellDataSet class"

    next
  }


  # ============================================================================
  # Reduction type
  # ============================================================================

  reduced_type_file <- file.path(
    grp_dir,
    "reduced_dim_type.txt"
  )


  reduced_type <- "lsi"


  if (file.exists(
    reduced_type_file
  )) {

    x <- readLines(
      reduced_type_file
    )


    if (length(x) > 0) {

      reduced_type <- tolower(
        trimws(
          x[1]
        )
      )
    }
  }


  message(
    "[DEBUG] Reduced dimension type: ",
    reduced_type
  )


  # ============================================================================
  # Obtain UMAP coordinates
  # ============================================================================

  if (
    reduced_type == "umap" &&
    file.exists(
      file.path(
        grp_dir,
        "umap_coords.tsv"
      )
    )
  ) {


    # --------------------------------------------------------------------------
    # Use exported UMAP
    # --------------------------------------------------------------------------

    message(
      "[DEBUG] Reusing exported UMAP..."
    )


    umap_coords <- tryCatch(

      read.delim(
        file.path(
          grp_dir,
          "umap_coords.tsv"
        ),
        row.names = 1,
        check.names = FALSE
      ),

      error = function(e) {

        message(
          "[ERROR] UMAP: ",
          conditionMessage(e)
        )

        NULL
      }
    )


    if (is.null(umap_coords)) {

      skip_log[[grp]] <- "failed: UMAP"

      next
    }


  } else {


    # --------------------------------------------------------------------------
    # Compute UMAP from exported LSI
    # --------------------------------------------------------------------------

    lsi_file <- file.path(
      grp_dir,
      "lsi_coords.tsv"
    )


    if (!file.exists(
      lsi_file
    )) {

      message(
        "[ERROR] Missing LSI coordinates."
      )


      skip_log[[grp]] <- "failed: LSI"

      next
    }


    message(
      "[DEBUG] Reading exported LSI..."
    )


    lsi <- tryCatch(

      read.delim(
        lsi_file,
        row.names = 1,
        check.names = FALSE
      ),

      error = function(e) {

        message(
          "[ERROR] LSI: ",
          conditionMessage(e)
        )

        NULL
      }
    )


    if (is.null(lsi)) {

      skip_log[[grp]] <- "failed: LSI"

      next
    }


    if (!all(
      cell_ids %in% rownames(lsi)
    )) {

      message(
        "[ERROR] LSI missing cells."
      )


      skip_log[[grp]] <- "failed: incomplete LSI"

      next
    }


    lsi <- lsi[
      cell_ids,
      ,
      drop = FALSE
    ]


    if (any(
      !is.finite(
        as.matrix(lsi)
      )
    )) {

      message(
        "[ERROR] LSI contains non-finite values."
      )


      skip_log[[grp]] <- "failed: invalid LSI"

      next
    }


    if (!requireNamespace(
      "uwot",
      quietly = TRUE
    )) {

      message(
        "[ERROR] uwot is required."
      )


      skip_log[[grp]] <- "failed: uwot unavailable"

      next
    }


    message(
      "[DEBUG] Computing UMAP from exported LSI..."
    )


    set.seed(123)


    umap_matrix <- tryCatch(

      uwot::umap(
        as.matrix(lsi),
        n_neighbors = 30,
        min_dist = 0.3,
        metric = "cosine",
        n_components = 2,
        verbose = TRUE
      ),

      error = function(e) {

        message(
          "[ERROR] uwot UMAP: ",
          conditionMessage(e)
        )

        NULL
      }
    )


    if (is.null(umap_matrix)) {

      skip_log[[grp]] <- "failed: UMAP"

      next
    }


    umap_coords <- as.data.frame(
      umap_matrix
    )


    colnames(umap_coords) <- c(
      "UMAP1",
      "UMAP2"
    )


    rownames(umap_coords) <- cell_ids


    # --------------------------------------------------------------------------
    # Free LSI immediately
    # --------------------------------------------------------------------------

    rm(lsi)

    gc(
      verbose = FALSE
    )
  }


  # ============================================================================
  # UMAP validation
  # ============================================================================

  if (!all(
    cell_ids %in% rownames(umap_coords)
  )) {

    message(
      "[ERROR] UMAP missing cells."
    )


    skip_log[[grp]] <- "failed: incomplete UMAP"

    next
  }


  umap_coords <- umap_coords[
    cell_ids,
    ,
    drop = FALSE
  ]


  if (ncol(umap_coords) < 2) {

    message(
      "[ERROR] UMAP has fewer than 2 dimensions."
    )


    skip_log[[grp]] <- "failed: invalid UMAP"

    next
  }


  umap_coords <- umap_coords[
    ,
    1:2,
    drop = FALSE
  ]


  colnames(umap_coords) <- c(
    "UMAP1",
    "UMAP2"
  )


  if (any(
    !is.finite(
      as.matrix(umap_coords)
    )
  )) {

    message(
      "[ERROR] UMAP contains non-finite values."
    )


    skip_log[[grp]] <- "failed: invalid UMAP values"

    next
  }


  message(
    "[DEBUG] UMAP dimensions: ",
    nrow(umap_coords),
    " x ",
    ncol(umap_coords)
  )


  # ============================================================================
  # make_cicero_cds
  # ============================================================================

  message(
    "[DEBUG] Running make_cicero_cds()..."
  )


  cicero_cds <- tryCatch(

    cicero::make_cicero_cds(
      cds,
      reduced_coordinates = umap_coords,
      k = CICERO_K
    ),

    error = function(e) {

      message(
        "[ERROR] make_cicero_cds: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(cicero_cds)) {

    skip_log[[grp]] <- "failed: make_cicero_cds"

    next
  }


  message(
    "[DEBUG] Cicero CDS created."
  )


  message(
    "[DEBUG] Aggregated cell groups: ",
    ncol(cicero_cds)
  )


  # ============================================================================
  # Distance parameter
  # ============================================================================

  message(
    "[DEBUG] Estimating distance parameter..."
  )


  dist_param_result <- tryCatch(

    cicero::estimate_distance_parameter(
      cicero_cds,
      window = CICERO_WINDOW,
      distance_constraint = CICERO_DISTANCE_CONSTRAINT,
      genomic_coords = genomic_coords,
      sample_num = 100
    ),

    error = function(e) {

      message(
        "[ERROR] estimate_distance_parameter: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(dist_param_result)) {

    skip_log[[grp]] <- "failed: distance parameter"

    next
  }


  dist_values <- suppressWarnings(
    as.numeric(
      unlist(
        dist_param_result
      )
    )
  )


  dist_values <- dist_values[
    is.finite(dist_values)
  ]


  if (length(dist_values) == 0) {

    message(
      "[ERROR] No finite distance parameters."
    )


    skip_log[[grp]] <- "failed: invalid distance parameter"

    next
  }


  mean_distance_parameter <- mean(
    dist_values
  )


  message(
    "[DEBUG] Mean distance_parameter: ",
    signif(
      mean_distance_parameter,
      8
    )
  )


  # ============================================================================
  # Generate Cicero models
  # ============================================================================

  message(
    "[DEBUG] Generating Cicero models..."
  )


  cicero_models <- tryCatch(

    cicero::generate_cicero_models(
      cicero_cds,
      distance_parameter = mean_distance_parameter,
      window = CICERO_WINDOW,
      genomic_coords = genomic_coords
    ),

    error = function(e) {

      message(
        "[ERROR] generate_cicero_models: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (is.null(cicero_models)) {

    skip_log[[grp]] <- "failed: generate_cicero_models"

    next
  }


  # ============================================================================
  # IMPORTANT MEMORY STEP
  #
  # At this stage we no longer need:
  #
  #   cds
  #   cicero_cds
  #   mat
  #   peak_df
  #   pd
  #   fd
  #   umap_coords
  #   peak_ids
  #   cell_ids
  #
  # But we MUST keep cicero_models until assemble_connections() finishes.
  # ============================================================================

  rm(
    cds,
    cicero_cds,
    mat,
    peak_df,
    pd,
    fd,
    umap_coords,
    peak_ids,
    cell_ids
  )


  gc(
    verbose = FALSE
  )


  message(
    "[DEBUG] Memory cleanup completed before assemble_connections()."
  )


  # ============================================================================
  # Assemble ALL connections
  #
  # This is the one unavoidable peak-memory step:
  # Cicero returns the complete connection table here.
  # ============================================================================

  message(
    "[DEBUG] Assembling Cicero connections..."
  )


  conns <- tryCatch(

    cicero::assemble_connections(
      cicero_models,
      silent = FALSE
    ),

    error = function(e) {

      message(
        "[ERROR] assemble_connections: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  # ============================================================================
  # Cicero models are no longer needed
  # ============================================================================

  rm(
    cicero_models
  )


  gc(
    verbose = FALSE
  )


  # ============================================================================
  # Check assembled connections
  # ============================================================================

  if (is.null(conns) ||
      nrow(conns) == 0) {

    message(
      "[RESULT] ",
      grp,
      ": no connections returned."
    )


    skip_log[[grp]] <- "empty: assemble_connections"

    rm(
      conns
    )


    gc(
      verbose = FALSE
    )


    next
  }


  message(
    "[RESULT] ",
    grp,
    ": ",
    format(
      nrow(conns),
      big.mark = ","
    ),
    " total peak pairs assembled"
  )


  # ============================================================================
  # IMPORTANT:
  # Filter immediately.
  #
  # We use a logical index rather than making additional derived data frames.
  # ============================================================================

  keep <- (
    !is.na(
      conns$coaccess
    ) &
      abs(
        conns$coaccess
      ) > COACCESS_THRESHOLD
  )


  n_strong <- sum(
    keep
  )


  message(
    "[RESULT] ",
    grp,
    ": ",
    format(
      n_strong,
      big.mark = ","
    ),
    " pairs with |coaccess| > ",
    COACCESS_THRESHOLD
  )


  # ============================================================================
  # If nothing passes threshold
  # ============================================================================

  if (n_strong == 0) {

    message(
      "[RESULT] ",
      grp,
      ": no connections pass threshold."
    )


    # Save an empty file with column names
    write.table(
      conns[
        FALSE,
        ,
        drop = FALSE
      ],
      file = outfile,
      sep = "\t",
      row.names = FALSE,
      quote = FALSE
    )


    cicero_summary[[grp]] <- data.frame(
      group = grp,
      n_connections_total = nrow(conns),
      n_connections_threshold = 0,
      threshold = COACCESS_THRESHOLD,
      stringsAsFactors = FALSE
    )


    rm(
      keep,
      conns
    )


    gc(
      verbose = FALSE
    )


    next
  }


  # ============================================================================
  # FILTER IN PLACE AS EARLY AS POSSIBLE
  #
  # After this assignment, only threshold-passing connections remain.
  # ============================================================================

  conns <- conns[
    keep,
    ,
    drop = FALSE
  ]


  rm(
    keep
  )


  gc(
    verbose = FALSE
  )


  message(
    "[DEBUG] Full connection table released."
  )


  message(
    "[DEBUG] Retained connection rows: ",
    format(
      nrow(conns),
      big.mark = ","
    )
  )


  # ============================================================================
  # Pair type classification ONLY on retained connections
  # ============================================================================

  if (all(
    c(
      "Peak1",
      "Peak2"
    ) %in% colnames(conns)
  )) {

    conns$pair_type <- classify_pair_type(
      conns$Peak1,
      conns$Peak2,
      peak_type_lookup
    )

  } else {

    message(
      "[WARNING] Peak1/Peak2 columns not found."
    )

    conns$pair_type <- "Unknown"
  }


  # ============================================================================
  # Pair-type summary
  # ============================================================================

  if (nrow(conns) > 0) {

    pt_strong <- table(
      conns$pair_type
    )


    pairtype_summary[[grp]] <- data.frame(
      group = grp,
      pair_type = names(pt_strong),
      n = as.integer(pt_strong),
      stringsAsFactors = FALSE
    )
  }


  # ============================================================================
  # Distance sanity check on retained connections only
  # ============================================================================

  if (all(
    c(
      "Peak1",
      "Peak2"
    ) %in% colnames(conns)
  )) {


    p1_split <- str_split_fixed(
      conns$Peak1,
      "_",
      3
    )


    p2_split <- str_split_fixed(
      conns$Peak2,
      "_",
      3
    )


    p1_start <- suppressWarnings(
      as.numeric(
        p1_split[, 2]
      )
    )


    p2_start <- suppressWarnings(
      as.numeric(
        p2_split[, 2]
      )
    )


    pair_dist <- abs(
      p1_start - p2_start
    )


    finite_dist <- pair_dist[
      is.finite(pair_dist)
    ]


    if (length(finite_dist) > 0) {

      message(
        "[CHECK] Max retained pair distance: ",
        round(
          max(finite_dist) / 1e6,
          3
        ),
        " Mb"
      )
    }


    # Release temporary distance objects
    rm(
      p1_split,
      p2_split,
      p1_start,
      p2_start,
      pair_dist,
      finite_dist
    )
  }


  # ============================================================================
  # Write ONLY threshold-passing connections
  # ============================================================================

  message(
    "[DEBUG] Writing filtered connections..."
  )


  write.table(
    conns,
    file = outfile,
    sep = "\t",
    row.names = FALSE,
    quote = FALSE
  )


  message(
    "[RESULT] Saved: ",
    outfile
  )


  # ============================================================================
  # Generate CCANs
  #
  # IMPORTANT:
  # We explicitly tell Cicero to use 0.2.
  #
  # Because conns has already been filtered to >0.2, the CCAN step works only
  # on retained connections and avoids carrying the 41M-row table.
  # ============================================================================

  message(
    "[DEBUG] Generating CCANs with cutoff ",
    COACCESS_THRESHOLD,
    "..."
  )


  ccans <- tryCatch(

    cicero::generate_ccans(
      conns,
      coaccess_cutoff_override = COACCESS_THRESHOLD
    ),

    error = function(e) {

      message(
        "[WARNING] generate_ccans: ",
        conditionMessage(e)
      )

      NULL
    }
  )


  if (!is.null(ccans) &&
      nrow(ccans) > 0) {


    n_ccans <- length(
      unique(
        ccans$CCAN
      )
    )


    mean_ccan_size <- round(
      nrow(ccans) / n_ccans,
      2
    )


    message(
      "[RESULT] ",
      grp,
      ": ",
      n_ccans,
      " CCANs; ",
      nrow(ccans),
      " peaks; mean size = ",
      mean_ccan_size
    )


    ccan_summary[[grp]] <- data.frame(
      group = grp,
      n_ccans = n_ccans,
      mean_ccan_size = mean_ccan_size,
      n_peaks_in_ccans = nrow(ccans),
      threshold = COACCESS_THRESHOLD,
      stringsAsFactors = FALSE
    )


    write.table(
      ccans,
      file = ccan_outfile,
      sep = "\t",
      row.names = FALSE,
      quote = FALSE
    )


    rm(
      ccans
    )


  } else {


    message(
      "[RESULT] ",
      grp,
      ": no CCANs formed."
    )


    ccan_summary[[grp]] <- data.frame(
      group = grp,
      n_ccans = 0,
      mean_ccan_size = NA_real_,
      n_peaks_in_ccans = 0,
      threshold = COACCESS_THRESHOLD,
      stringsAsFactors = FALSE
    )
  }


  # ============================================================================
  # Connection summary
  # ============================================================================

  cicero_summary[[grp]] <- data.frame(
    group = grp,
    n_connections_total = NA_integer_,
    n_connections_threshold = nrow(conns),
    threshold = COACCESS_THRESHOLD,
    stringsAsFactors = FALSE
  )


  # ============================================================================
  # Get total from output if desired:
  #
  # We intentionally do NOT retain the original 41M-row number in memory after
  # filtering. The exact total assembled is printed above but not carried as a
  # giant object.
  # ============================================================================


  # ============================================================================
  # Final memory cleanup for group
  # ============================================================================

  rm(
    conns
  )


  gc(
    verbose = FALSE
  )


  elapsed_min <- as.numeric(
    difftime(
      Sys.time(),
      t_grp,
      units = "mins"
    )
  )


  message(
    "[DEBUG] Group elapsed: ",
    round(
      elapsed_min,
      2
    ),
    " min"
  )


  message(
    "---- Finished group: ",
    grp,
    " ----"
  )
}


# ==============================================================================
# SUMMARY: Cicero
# ==============================================================================

if (length(cicero_summary) > 0) {

  summary_df <- do.call(
    rbind,
    cicero_summary
  )


  summary_df <- summary_df[
    order(
      -summary_df$n_connections_threshold
    ),
    ,
    drop = FALSE
  ]


  message("")
  message("============================================================")
  message(" CICERO SUMMARY")
  message("============================================================")


  print(
    summary_df,
    row.names = FALSE
  )


  write.table(
    summary_df,
    file = file.path(
      out_dir,
      "SUMMARY_cicero.tsv"
    ),
    sep = "\t",
    row.names = FALSE,
    quote = FALSE
  )
}


# ==============================================================================
# SUMMARY: CCANs
# ==============================================================================

if (length(ccan_summary) > 0) {

  ccan_df <- do.call(
    rbind,
    ccan_summary
  )


  ccan_df <- ccan_df[
    order(
      -ccan_df$n_ccans
    ),
    ,
    drop = FALSE
  ]


  write.table(
    ccan_df,
    file = file.path(
      out_dir,
      "SUMMARY_ccans.tsv"
    ),
    sep = "\t",
    row.names = FALSE,
    quote = FALSE
  )
}


# ==============================================================================
# SUMMARY: Pair types
# ==============================================================================

if (length(pairtype_summary) > 0) {

  valid_pairtypes <- pairtype_summary[
    !vapply(
      pairtype_summary,
      is.null,
      logical(1)
    )
  ]


  if (length(valid_pairtypes) > 0) {

    pairtype_df <- do.call(
      rbind,
      valid_pairtypes
    )


    if (nrow(pairtype_df) > 0) {

      pairtype_wide <- reshape(
        pairtype_df,
        idvar = "group",
        timevar = "pair_type",
        direction = "wide"
      )


      colnames(pairtype_wide) <- gsub(
        "^n\\.",
        "",
        colnames(pairtype_wide)
      )


      write.table(
        pairtype_wide,
        file = file.path(
          out_dir,
          "SUMMARY_pairtypes.tsv"
        ),
        sep = "\t",
        row.names = FALSE,
        quote = FALSE,
        na = "0"
      )
    }
  }
}


# ==============================================================================
# Failed groups
# ==============================================================================

message("")
message("============================================================")
message(" GROUPS SKIPPED / FAILED")
message("============================================================")


if (length(skip_log) > 0) {

  for (grp in names(skip_log)) {

    message(
      "[FAILED] ",
      grp,
      ": ",
      skip_log[[grp]]
    )
  }


  skip_df <- data.frame(
    group = names(skip_log),
    reason = unlist(
      skip_log
    ),
    stringsAsFactors = FALSE
  )


  write.table(
    skip_df,
    file = file.path(
      out_dir,
      "SUMMARY_failed_groups.tsv"
    ),
    sep = "\t",
    row.names = FALSE,
    quote = FALSE
  )

} else {

  message(
    "None"
  )
}


# ==============================================================================
# Final
# ==============================================================================

message("")
message("============================================================")
message(" DONE")
message("============================================================")
